// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address sender, uint256 existingBalance, uint256 sendValue) public {
        sendValue = bound(sendValue, 0, type(uint128).max);
        existingBalance = bound(existingBalance, 0, type(uint128).max);
        vm.assume(sender != address(0));
        if (existingBalance > 0) {
            vm.deal(sender, existingBalance);
            vm.prank(sender);
            c.addToBalance{value: existingBalance}();
        }
        uint256 balanceBefore = c.getBalance(sender);
        vm.deal(sender, sendValue);
        vm.prank(sender);
        c.addToBalance{value: sendValue}();
        uint256 balanceAfter = c.getBalance(sender);
        assertTrue(balanceAfter == balanceBefore + sendValue);
    }
}
